```javascript
/**
 * Bargain Drop - Automated Repricer Worker
 * CIP Pipeline: GitHub Shards -> Price Calculation -> Shopify GraphQL API
 */

export default {
  // Cron trigger handler
  async scheduled(event, env, ctx) {
    ctx.waitUntil(runRepricer(env));
  },

  // Manual trigger endpoint for testing
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === "/run" && request.method === "POST") {
      const summary = await runRepricer(env);
      return new Response(JSON.stringify(summary, null, 2), {
        headers: { "Content-Type": "application/json" }
      });
    }
    return new Response("Bargain Drop Repricer Worker active. POST to /run to trigger manually.", { status: 200 });
  }
};

/**
 * Locked Pricing Matrix Formula
 */
function calculatePrice(usdCost) {
  let multiplier;
  if (usdCost < 10.00) {
    multiplier = 3.2;
  } else if (usdCost <= 15.00) {
    multiplier = 2.8;
  } else if (usdCost <= 22.00) {
    multiplier = 2.5;
  } else if (usdCost <= 30.00) {
    multiplier = 2.2;
  } else if (usdCost <= 60.00) {
    multiplier = 1.9;
  } else {
    multiplier = 1.7;
  }

  const FX_RATE = 1.4234;
  const rawPrice = usdCost * multiplier * FX_RATE;
  const finalPrice = Math.ceil(rawPrice) - 0.05;

  return {
    price: finalPrice.toFixed(2),
    compareAtPrice: null
  };
}

/**
 * Core Execution Pipeline
 */
async function runRepricer(env) {
  const stats = { scanned: 0, updated: 0, errors: [] };

  try {
    // 1. Fetch catalog data from GitHub Shards
    const shardResponse = await fetch(`https://api.github.com/repos/${env.GITHUB_REPO}/contents/shards`, {
      headers: {
        "Authorization": `Bearer ${env.GITHUB_TOKEN}`,
        "User-Agent": "BargainDrop-Repricer"
      }
    });

    if (!shardResponse.ok) {
      throw new Error(`GitHub Shards fetch failed: ${shardResponse.statusText}`);
    }

    const shardFiles = await shardResponse.json();

    for (const file of shardFiles) {
      if (!file.name.endsWith('.json')) continue;

      const fileRes = await fetch(file.download_url);
      const items = await fileRes.json();

      for (const item of items) {
        stats.scanned++;
        const targetPricing = calculatePrice(item.cost_usd);

        // 2. Check & update Shopify variant price if mismatched
        if (item.shopify_variant_id) {
          const updated = await updateShopifyVariant(
            env,
            item.shopify_variant_id,
            targetPricing.price,
            targetPricing.compareAtPrice
          );
          if (updated) stats.updated++;
        }
      }
    }
  } catch (err) {
    stats.errors.push(err.message);
  }

  return stats;
}

/**
 * Shopify Admin GraphQL Price Update Mutation
 */
async function updateShopifyVariant(env, variantId, price, compareAtPrice) {
  const query = `
    mutation productVariantUpdate($input: ProductVariantInput!) {
      productVariantUpdate(input: $input) {
        productVariant {
          id
          price
          compareAtPrice
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const response = await fetch(`https://${env.SHOPIFY_STORE_DOMAIN}/admin/api/2024-01/graphql.json`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Shopify-Access-Token": env.SHOPIFY_ADMIN_TOKEN
    },
    body: JSON.stringify({
      query,
      variables: {
        input: {
          id: variantId,
          price: price,
          compareAtPrice: compareAtPrice
        }
      }
    })
  });

  const resData = await response.json();
  const userErrors = resData?.data?.productVariantUpdate?.userErrors;

  if (userErrors && userErrors.length > 0) {
    console.error(`Shopify update error for ${variantId}:`, userErrors);
    return false;
  }

  return true;
}
```

